def collatz(number):
    if number % 2 == 0:
        result = number // 2
    else:
        result = 3 * number + 1
    print(result, end=' ')
    return result
number = int(input('Enter number: '))
print(number, end=' ')
while number != 1:
    number = collatz(number)
print()

